export function MacrothemeIcon({ icone, color }) {
  const style = color ? { color } : undefined;
  return (
    <svg className="macrotheme-icon" viewBox={MACROTHEME_VIEWBOXES[icone] || '0 0 24 24'} style={style} fill={color || undefined} preserveAspectRatio="xMidYMid meet">
      {MACROTHEME_ICONS[icone] || (
        <path d="M4 17h16M7 15l3-4 3 3 4-6 3 7" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
      )}
    </svg>
  );
}

