export function IndicatorIcon({ icone, cor }) {
  // Indicadores sem ícone dedicado (ver _ICONE_POR_BASE em utils/cover.py)
  // recebem o `icone` do macrotema (ex: "wrench") como fallback. Essas chaves
  // só existem em MACROTHEME_ICONS, não em INDICATOR_ICONS, então sem este
  // segundo lookup o ícone caía no traço genérico + vermelho fixo da CSS
  // (.indicator-icon), em vez do desenho e da cor do tema.
  if (INDICATOR_ICONS[icone]) {
    return (
      <svg className="indicator-icon" viewBox="0 0 24 24" aria-hidden="true">
        {INDICATOR_ICONS[icone]}
      </svg>
    );
  }
  if (MACROTHEME_ICONS[icone]) {
    return (
      <svg
        className="indicator-icon"
        viewBox={MACROTHEME_VIEWBOXES[icone] || '0 0 24 24'}
        style={cor ? { color: cor } : undefined}
        aria-hidden="true"
      >
        {MACROTHEME_ICONS[icone]}
      </svg>
    );
  }
  return (
    <svg className="indicator-icon" viewBox="0 0 24 24" style={cor ? { color: cor } : undefined} aria-hidden="true">
      <path d="M4 17h16M7 15l3-4 3 3 4-6 3 7" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  );
}
